-- свой набор сервисов у бренда (тот же список — build/brand/exclude.json): товары без заказов удаляем, с заказами — скрываем
delete from products p where p.slug in ('artflow','artlist','chaton','chess-com','civitai','clipdrop','craiyon','deevid','deezer','elevenlabs','epic-games','evernote','fireflies','flora','flux','fusara','gamma','gog','hedra','heygen','higgsfield','istock','ltx-studio','novelai','openart','playstation','qobuz','qodo','recraft','revid','roblox','roland','stable-diffusion','windows-pro-11') and not exists (select 1 from orders o where o.product_id = p.id);
update products set active = false where slug in ('artflow','artlist','chaton','chess-com','civitai','clipdrop','craiyon','deevid','deezer','elevenlabs','epic-games','evernote','fireflies','flora','flux','fusara','gamma','gog','hedra','heygen','higgsfield','istock','ltx-studio','novelai','openart','playstation','qobuz','qodo','recraft','revid','roblox','roland','stable-diffusion','windows-pro-11');
